__NUXT_JSONP__("/ru/how-to-apply/student-visa-f1", {data:[{details:{slug:"ru",pageTitle:"Студенческая виза F1 | Mentor Language Institute",pageDescription:"Выберите один из вариантов ниже. Если вы не уверены какой вариант выбрать нажмите ЧИТАТЬ БОЛЬШЕ для дополнительной информации.",title:"Студенческая виза F1",image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fvisa_application.jpg",subtitle:["Выберите один из вариантов ниже. \u003Cbr \u002F\u003E Если вы не уверены какой вариант выбрать нажмите ЧИТАТЬ БОЛЬШЕ для дополнительной информации."],category:[{btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas_btn_ru.png",link:"\u002Fru\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas-students"},btn_transfer:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer_student_btn_ru.png",link:"\u002Fru\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students"},btn_status:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange_status_btn_ru.png",link:"\u002Fru\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status"}}],content:{subtitle:"Есть вопросы?",description:["Как правило, вам понадобится студенческая виза для пребывания в Соединенных Штатах в качестве долгосрочного студента.","Если вы не знаете, нужна ли вам виза или нет, свяжитесь с нами.","Наши сотрудники говорят на 8 разных языках."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-ru.jpg",link:"\u002Fru\u002Fcontact"}},dir:"\u002Fstudent-visa-f1",path:"\u002Fstudent-visa-f1\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:31.130Z",updatedAt:"2025-05-26T12:06:27.926Z"}}],fetch:{},mutations:void 0});